        if n>=0.8*h:
            col_lines.append(c)
    def has_marker_row(r):
        color=Counter(grid[r]).most_common(1)[0][0]
        return any(v!=color for v in grid[r])
    def has_marker_col(c):
        vals=[grid[r][c] for r in range(h)]
        color=Counter(vals).most_common(1)[0][0]
        return any(v!=color for v in vals)
    marked_r=[r for r in row_lines if has_marker_row(r)]
    marked_c=[c for c in col_lines if has_marker_col(c)]
    if len(marked_r)>=2:
        row_lines=[r for r in row_lines if marked_r[0]<=r<=marked_r[-1]]
    if len(marked_c)>=2:
